import{_ as n,o as i,c as e,a3 as l}from"./chunks/framework.BvvarXmc.js";const t="/screenshots/tabungan.png",r="/screenshots/infaq.png",h=JSON.parse('{"title":"Tabungan Siswa & Dana Infaq Sekolah","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-keuangan/tabungan-infaq.md","filePath":"panduan-keuangan/tabungan-infaq.md","lastUpdated":null}'),s={name:"panduan-keuangan/tabungan-infaq.md"};function o(u,a,k,g,m,p){return i(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="tabungan-siswa-dana-infaq-sekolah" tabindex="-1">Tabungan Siswa &amp; Dana Infaq Sekolah <a class="header-anchor" href="#tabungan-siswa-dana-infaq-sekolah" aria-label="Permalink to &quot;Tabungan Siswa &amp; Dana Infaq Sekolah&quot;">​</a></h1><p>Aplikasi menyediakan modul khusus untuk mengelola Tabungan Pintar siswa secara akurat serta pencatatan donasi kotak infaq sekolah secara transparan.</p><hr><h2 id="_1-tampilan-rekening-tabungan-siswa" tabindex="-1">1. Tampilan Rekening Tabungan Siswa <a class="header-anchor" href="#_1-tampilan-rekening-tabungan-siswa" aria-label="Permalink to &quot;1. Tampilan Rekening Tabungan Siswa&quot;">​</a></h2><p><img src="'+t+'" alt="Tabungan Siswa"></p><h3 id="alur-setor-tarik-tabungan-siswa" tabindex="-1">Alur Setor &amp; Tarik Tabungan Siswa: <a class="header-anchor" href="#alur-setor-tarik-tabungan-siswa" aria-label="Permalink to &quot;Alur Setor &amp; Tarik Tabungan Siswa:&quot;">​</a></h3><ol><li><strong>Setor Tabungan</strong>: <ul><li>Cari siswa atau scan kartu siswa.</li><li>Klik tombol <strong><code>+ Setor Tabungan</code></strong>.</li><li>Masukkan nominal uang yang disetor (misal: <code>Rp 50.000</code>).</li><li>Masukkan catatan setoran, lalu klik <strong>Simpan &amp; Cetak Struk</strong>.</li></ul></li><li><strong>Tarik Tabungan</strong>: <ul><li>Cari siswa pada tabel tabungan.</li><li>Klik tombol <strong><code>- Tarik Tabungan</code></strong>.</li><li>Masukkan nominal penarikan (sistem otomatis menolak jika nominal melebihi sisa saldo).</li><li>Klik <strong>Konfirmasi Penarikan</strong>.</li></ul></li></ol><hr><h2 id="_2-tampilan-pengelolaan-infaq-sekolah" tabindex="-1">2. Tampilan Pengelolaan Infaq Sekolah <a class="header-anchor" href="#_2-tampilan-pengelolaan-infaq-sekolah" aria-label="Permalink to &quot;2. Tampilan Pengelolaan Infaq Sekolah&quot;">​</a></h2><p><img src="'+r+'" alt="Manajemen Infaq"></p><h3 id="alur-penerimaan-penyaluran-infaq" tabindex="-1">Alur Penerimaan &amp; Penyaluran Infaq: <a class="header-anchor" href="#alur-penerimaan-penyaluran-infaq" aria-label="Permalink to &quot;Alur Penerimaan &amp; Penyaluran Infaq:&quot;">​</a></h3><ol><li><strong>Penerimaan Infaq</strong>: <ul><li>Klik <strong><code>+ Catat Infaq Masuk</code></strong>.</li><li>Pilih program (Infaq Jumat Berkah, Donasi Renovasi Masjid, Santunan Yatim).</li><li>Masukkan nominal uang yang diterima, lalu klik simpan.</li></ul></li><li><strong>Penyaluran Infaq</strong>: <ul><li>Klik <strong><code>- Penyaluran Dana Infaq</code></strong>.</li><li>Masukkan keperluan penyaluran dan lampirkan bukti nota/kuitansi pengeluaran.</li><li>Sistem mencatat saldo akhir dana infaq yang dapat dilaporkan secara transparan ke seluruh warga sekolah.</li></ul></li></ol>',12)])])}const c=n(s,[["render",o]]);export{h as __pageData,c as default};
